%% additional definitions required by the score:
D = \tweak Stem.direction #DOWN \etc
U = \tweak Stem.direction #UP \etc


\header {
  texidoc = "Two voices share one staff. To each voice some lyrics is assigned
    (with the lyrics of voice one positioned above the staff). In the last bar,
    the second voice is empty, thus the full rest should be placed on the
    staff's default position."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative e'' {
  \clef "treble" \time 4/4 \key c \major \U e2 ^> ^\fermata \U d4 _\mf \U b4 | % 1
  a'4\rest \U d,4 \U b,4. ( \U c'8 ) | % 2
  \oneVoice R1 \bar "|."
}

PartPOneVoiceOneLyricsOne = \lyricmode {
  \set ignoreMelismata = ##t
  \set includeGraceNotes = ##t
  This is the lyrics of "Voice1"
}

PartPOneVoiceTwo = \relative c'' {
  \clef "treble" \time 4/4 \key c \major \D c2 _> _\fermata \D b4 \D g4 | % 1
  c,4\rest \D b'4 \D g,4. ( \D a'8 ) s1 \bar "|."
}

