          alignAboveContext = "P1"
          } \lyricsto "PartPOneVoiceOne" {
          \PartPOneVoiceOneLyricsOne
        }
        \context Voice = "PartPOneVoiceTwo" {
          \voiceTwo \PartPOneVoiceTwo
        }
        \new Lyrics \lyricsto "PartPOneVoiceTwo" {
          \PartPOneVoiceTwoLyricsOne
        }
      >>
    >>
  >>
  \layout {}
